// The dashboard the server serves. Everything dynamic is escaped.
import { formatMoney } from "./metrics.mjs";
import { mrrChart } from "./chart.mjs";

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const pc = (v, d = 1) => (v === null || v === undefined ? "n/a" : `${(v * 100).toFixed(d)}%`);

// Logo retention by signup month: row = cohort, column = months since signup.
// Shading is only a visual cue; the number is always printed.
export function cohortTable(cohorts) {
  const rows = cohorts.filter((c) => c.size > 0);
  if (!rows.length) return "";
  const width = Math.max(...rows.map((c) => c.logo.length));
  const head = Array.from({ length: width }, (_, k) => `<th>M${k}</th>`).join("");
  const body = rows.map((c) => `<tr><td>${esc(c.month)}</td><td>${c.size}</td>${Array.from({ length: width }, (_, k) => c.logo[k] === undefined ? "<td></td>" : `<td class="c" style="background:rgba(67,56,202,${(0.08 + 0.4 * c.logo[k]).toFixed(2)})" title="${esc(c.month)} cohort, month ${k}: ${(c.revenue[k] * 100).toFixed(0)}% of starting MRR kept">${(c.logo[k] * 100).toFixed(0)}%</td>`).join("")}</tr>`).join("");
  return `<div class="card" style="margin-top:16px;overflow-x:auto"><h2 style="font-size:1rem;margin:0 0 8px">Retention by signup month</h2><table><thead><tr><th>Cohort</th><th>Subs</th>${head}</tr></thead><tbody>${body}</tbody></table><p class="note">Share of each month's new subscriptions still active at the end of month N (hover for the share of starting MRR kept, at today's prices). Cohorts older than the history window are not shown.</p></div>`;
}

// MRR by plan plus how much of it sits with the biggest customers. Customer
// ids are never shown, only shares, so a screenshot leaks no one.
export function planTable(b, currency) {
  if (!b || !b.plans?.length) return "";
  const rows = b.plans.map((p) => `<tr><td>${esc(p.plan)}</td><td>${esc(formatMoney(p.mrr, currency))}</td><td>${p.subs}</td><td>${(p.share * 100).toFixed(1)}%</td></tr>`).join("");
  const c = b.concentration;
  const note = c ? `Largest customer: ${(c.top1 * 100).toFixed(1)}% of MRR. Top ${Math.min(c.topN, c.customers)} customers: ${(c.top5 * 100).toFixed(1)}% across ${c.customers} paying customers.${c.top1 >= 0.2 ? " One customer above 20% is a risk worth planning for." : ""}` : "";
  const r = b.atRisk;
  const risk = r && r.subs ? ` ${esc(formatMoney(r.mrr, currency))} (${(r.share * 100).toFixed(1)}%) across ${r.subs} past-due subscription${r.subs === 1 ? "" : "s"} is at risk from failed payments: chase those before they cancel.` : "";
  return `<div class="card" style="margin-top:16px;overflow-x:auto"><h2 style="font-size:1rem;margin:0 0 8px">MRR by plan</h2><table><thead><tr><th>Plan</th><th>MRR</th><th>Subs</th><th>Share</th></tr></thead><tbody>${rows}</tbody></table><p class="note">${esc(note + risk)}</p></div>`;
}

// Run-rate projection table: three scenarios, every number printed.
export function forecastTable(f, currency) {
  if (!f) return "";
  const $ = (n) => esc(formatMoney(n, currency));
  const body = f.months.map((m, i) => `<tr><td>${esc(m)}</td><td>${$(f.low[i])}</td><td>${$(f.base[i])}</td><td>${$(f.high[i])}</td></tr>`).join("");
  return `<div class="card" style="margin-top:16px;overflow-x:auto"><h2 style="font-size:1rem;margin:0 0 8px">Run-rate projection</h2><table><thead><tr><th>Month</th><th>Low</th><th>Base</th><th>High</th></tr></thead><tbody>${body}</tbody></table><p class="note">Rolls the current MRR forward using the churn, contraction, expansion and new-business pace of ${esc(f.basis.join(", "))}. Base uses their average, Low the worst month, High the best. This is arithmetic on past months, not a prediction: one big customer moves it a lot.</p></div>`;
}

// Customer concentration: shares only, no customer identifiers.
export function concentrationCard(c) {
  if (!c) return "";
  const rows = c.top.map((x, i) => `<tr><td>#${i + 1} largest subscription</td><td>${pc(x)}</td></tr>`).join("");
  return `<div class="card" style="margin-top:16px;overflow-x:auto"><h2 style="font-size:1rem;margin:0 0 8px">Customer concentration: <span>${esc(c.risk)}</span> risk</h2><table><thead><tr><th>Share of MRR</th><th></th></tr></thead><tbody><tr><td>Largest subscription</td><td>${pc(c.top1)}</td></tr><tr><td>Top 5</td><td>${pc(c.top5)}</td></tr><tr><td>Top 10</td><td>${pc(c.top10)}</td></tr></tbody></table><p class="note">Across ${c.subscriptions} paying subscriptions. A customer with several subscriptions counts once per subscription. Rule of thumb used here: high if one subscription is 25% or more of MRR, moderate at 10% or more (or the top five at 50% or more). A rule of thumb, not advice.</p></div>`;
}

export function renderDashboard({ company, summary, months, currency, lastSyncAt, skipped, cohorts = [], breakdown = null, forecast = null, concentration = null }) {
  const $ = (n) => esc(formatMoney(n, currency));
  const r = summary?.rates || {};
  const tile = (label, value, sub = "") => `<div class="t"><div class="l">${esc(label)}</div><div class="v">${value}</div><div class="s">${esc(sub)}</div></div>`;
  const rows = [...months].reverse().map((m) => `<tr><td>${esc(m.month)}${m.approximate ? " <abbr title='Rebuilt from subscription dates at today&#39;s prices: no expansion or contraction'>~</abbr>" : ""}</td><td>${$(m.mrr)}</td><td>${m.customers}</td><td>+${$(m.new)}</td><td>+${$(m.expansion)}</td><td>+${$(m.reactivation)}</td><td>-${$(m.contraction)}</td><td>-${$(m.churn)}</td></tr>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(company)} · MRR Pulse</title>
<style>:root{font:16px system-ui,sans-serif;color:#1b1f2a;background:#f5f4fa}body{max-width:980px;margin:auto;padding:24px}h1{font-size:1.5rem;color:#2e2a74;margin:0 0 4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:16px 0}.t,.card{background:#fff;border:1px solid #dcdbec;border-radius:12px;padding:14px}.l{font-size:.8rem;color:#4a4a63}.v{font-size:1.5rem;font-weight:800;color:#2e2a74}.s{font-size:.78rem;color:#4a4a63}table{border-collapse:collapse;width:100%;font-size:.88rem}th,td{text-align:right;padding:6px 8px;border-bottom:1px solid #e8e7f3}th:first-child,td:first-child{text-align:left}.note{font-size:.84rem;color:#4a4a63}td.c{text-align:center;font-variant-numeric:tabular-nums}</style></head><body>
<h1>${esc(company)} · MRR Pulse</h1><p class="note">Last synced ${lastSyncAt ? esc(new Date(lastSyncAt).toISOString().replace("T", " ").slice(0, 16)) + " UTC" : "never"}. Read-only: this server cannot change anything in Stripe.${skipped ? ` ${skipped} subscription(s) in another currency were left out.` : ""}</p>
${summary ? `<div class="grid">${tile("MRR", $(summary.mrr), summary.growthPct === null ? "" : `${pc(summary.growthPct)} vs last month`)}${tile("ARR (MRR × 12)", $(summary.arr))}${tile("Customers", String(summary.customers), `ARPA ${formatMoney(summary.arpa, currency)}`)}${tile("Net new MRR", $(summary.netNew), summary.month + " so far")}${tile("Net revenue retention", pc(r.nrr), "month " + (r.basis || ""))}${tile("Logo churn", pc(r.logoChurn), "month " + (r.basis || ""))}${tile("Quick ratio", r.quickRatio === null || r.quickRatio === undefined ? "n/a" : r.quickRatio.toFixed(1), "(new+expansion) ÷ (churn+contraction)")}</div>
<div class="card">${mrrChart(months, currency)}</div>
<div class="card" style="margin-top:16px;overflow-x:auto"><table><thead><tr><th>Month</th><th>MRR</th><th>Cust.</th><th>New</th><th>Expansion</th><th>Reactiv.</th><th>Contraction</th><th>Churn</th></tr></thead><tbody>${rows}</tbody></table></div>
${forecastTable(forecast, currency)}${planTable(breakdown, currency)}${concentrationCard(concentration)}${cohortTable(cohorts)}` : `<p>No data yet. Click sync or wait for the first scheduled sync.</p>`}
<p class="note">MRR counts active and past-due subscriptions, normalises every price to a month, nets percent-off coupons, and excludes trials, paused subscriptions and metered usage. Months marked ~ were rebuilt from subscription dates at today's prices. Not financial or accounting advice.</p></body></html>`;
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted MRR dashboard for Stripe. Zero dependencies, read-only key.
//   STRIPE_SECRET_KEY=rk_... ADMIN_KEY=... COMPANY_NAME=Acme node server.mjs
// Open the URL, sign in with any user name and ADMIN_KEY as the password.
import http from "node:http";
import fs from "node:fs";
import { timingSafeEqual } from "node:crypto";
import { createStripe } from "./stripe.mjs";
import { backfill, applySync, liveMap, summarize, cohorts, breakdown, forecast, concentration, monthsCsv } from "./metrics.mjs";
import { renderDashboard } from "./page.mjs";
import { notify, validWebhook } from "./alerts.mjs";

export const newState = () => ({ months: {}, last: null, ever: {}, lastSyncAt: null, currency: null, cohorts: [], breakdown: null });

const eq = (a, b) => { const x = Buffer.from(a), y = Buffer.from(b); return x.length === y.length && timingSafeEqual(x, y); };
export function authorized(header, key) {
  if (!key || !header) return false;
  if (header.startsWith("Bearer ")) return eq(header.slice(7), key);
  if (header.startsWith("Basic ")) {
    const pw = Buffer.from(header.slice(6), "base64").toString().split(":").slice(1).join(":");
    return eq(pw, key);
  }
  return false;
}

// One pass: list subscriptions, pick the currency, fold into state.
export async function sync(cfg) {
  const all = await cfg.stripe.listSubscriptions();
  const live = all.filter((s) => s.status === "active" || s.status === "past_due");
  const counts = {};
  for (const s of live) counts[s.currency] = (counts[s.currency] || 0) + 1;
  const currency = cfg.currency || cfg.state.currency || Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "usd";
  const subs = all.filter((s) => s.currency === currency);
  const skipped = all.length - subs.length;
  const now = cfg.now();
  const cur = liveMap(subs, { countPastDue: cfg.countPastDue !== false });
  const st = cfg.state;
  if (!st.last) {
    const b = backfill(subs, now, cfg.months || 12);
    st.months = Object.fromEntries(b.months.map((m) => [m.month, m]));
    st.ever = b.ever;
    st.last = cur;
    const row = b.months[b.months.length - 1];
    row.mrr = Object.values(cur).reduce((a, v) => a + v, 0); row.customers = Object.keys(cur).length;
    for (const id of Object.keys(cur)) st.ever[id] = 1;
    st.lastSyncAt = now;
  } else applySync(st, cur, now);
  st.currency = currency; st.skipped = skipped;
  st.cohorts = cohorts(subs, now, cfg.months || 12);
  st.breakdown = breakdown(subs, { countPastDue: cfg.countPastDue !== false });
  cfg.save();
  try { await notify(cfg, monthList(st)); } catch (e) { console.error("alert failed:", e.message); }
  return { subscriptions: all.length, counted: Object.keys(cur).length, skipped };
}

export const monthList = (state) => Object.values(state.months).sort((a, b) => (a.month < b.month ? -1 : 1));

// cfg: {state, save, stripe, adminKey, company, currency, now, countPastDue, months}
export function handler(cfg) {
  let syncing = null;
  const runSync = () => (syncing ||= sync(cfg).finally(() => { syncing = null; }));
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json", extra = {}) => {
      res.writeHead(code, { "content-type": type, "cache-control": "no-store", "referrer-policy": "no-referrer", "x-content-type-options": "nosniff", ...extra });
      res.end(typeof body === "string" ? body : JSON.stringify(body));
    };
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (!authorized(req.headers.authorization, cfg.adminKey)) return send(401, "sign in with ADMIN_KEY as the password\n", "text/plain", { "www-authenticate": 'Basic realm="MRR Pulse", charset="UTF-8"' });
      const months = monthList(cfg.state);
      if (req.method === "GET" && url.pathname === "/") {
        return send(200, renderDashboard({ company: cfg.company || "Your company", summary: summarize(months), months, currency: cfg.state.currency || "usd", lastSyncAt: cfg.state.lastSyncAt, skipped: cfg.state.skipped, cohorts: cfg.state.cohorts || [], forecast: forecast(months), breakdown: cfg.state.breakdown, concentration: concentration(cfg.state.last || {}) }), "text/html; charset=utf-8", { "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'" });
      }
      if (req.method === "GET" && url.pathname === "/v1/metrics") return send(200, { currency: cfg.state.currency, lastSyncAt: cfg.state.lastSyncAt, summary: summarize(months) });
      if (req.method === "GET" && url.pathname === "/v1/forecast") return send(200, forecast(months, { horizon: Math.min(24, Math.max(1, Number(url.searchParams.get("months")) || 6)) }));
      if (req.method === "GET" && url.pathname === "/v1/concentration") return send(200, concentration(cfg.state.last || {}));
      if (req.method === "GET" && url.pathname === "/v1/cohorts") return send(200, cfg.state.cohorts || []);
      if (req.method === "GET" && url.pathname === "/v1/plans") return send(200, cfg.state.breakdown || { total: 0, plans: [], concentration: null });
      if (req.method === "GET" && url.pathname === "/v1/months.csv") return send(200, monthsCsv(months, cfg.state.currency || "usd"), "text/csv; charset=utf-8", { "content-disposition": 'attachment; filename="mrr-pulse-months.csv"' });
      if (req.method === "GET" && url.pathname === "/v1/months") return send(200, months);
      if (req.method === "POST" && url.pathname === "/v1/sync") return send(200, await runSync());
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status && e.status < 500 ? 502 : 500, { error: "sync failed; check STRIPE_SECRET_KEY and the server log" });
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const env = process.env;
  const missing = ["STRIPE_SECRET_KEY", "ADMIN_KEY"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  if (env.ADMIN_KEY.length < 12) { console.error("ADMIN_KEY must be at least 12 characters"); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = Object.assign(newState(), readJson(statePath, {}));
  if (env.ALERT_WEBHOOK_URL && !validWebhook(env.ALERT_WEBHOOK_URL)) { console.error("ALERT_WEBHOOK_URL must be an https URL"); process.exit(1); }
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  const cfg = { state, save, stripe: createStripe({ key: env.STRIPE_SECRET_KEY, maxPages: Number(env.MAX_PAGES) || 500 }), adminKey: env.ADMIN_KEY, company: env.COMPANY_NAME, currency: env.CURRENCY && env.CURRENCY.toLowerCase(), countPastDue: env.COUNT_PAST_DUE !== "false", months: Number(env.HISTORY_MONTHS) || 12, now: Date.now, webhook: env.ALERT_WEBHOOK_URL, digestDays: env.DIGEST_DAYS === undefined ? 7 : Number(env.DIGEST_DAYS), churnAlertPct: (Number(env.CHURN_ALERT_PCT) || 5) / 100 };
  const h = handler(cfg);
  const tick = () => sync(cfg).then((r) => console.log("synced", JSON.stringify(r)), (e) => console.error("sync failed:", e.message));
  http.createServer(h).listen(Number(env.PORT || 8080), () => {
    console.log(`mrr-pulse on :${env.PORT || 8080}`);
    tick(); setInterval(tick, Math.max(5, Number(env.SYNC_MINUTES) || 360) * 60000).unref();
  });
}

